import React, { useState } from "react";
import "./App.css"; // or your styling file

export default function AuthForm() {
  const [isSignUp, setIsSignUp] = useState(true);
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [message, setMessage] = useState("");
  const [isError, setIsError] = useState(false);

  // Get registered users from localStorage (or default to empty array)
  const getUsers = () => JSON.parse(localStorage.getItem("registeredUsers")) || [];

  const handleSubmit = (e) => {
    e.preventDefault();

    if (!email.trim() || !password.trim()) {
      setMessage("Please enter both email and password.");
      setIsError(true);
      return;
    }

    const users = getUsers();

    if (isSignUp) {
      // Check if user already exists
      const existingUser = users.find((u) => u.email === email);
      if (existingUser) {
        setMessage("User already exists! Please log in instead.");
        setIsError(true);
        return;
      }

      // Register new user
      const updatedUsers = [...users, { email, password }];
      localStorage.setItem("registeredUsers", JSON.stringify(updatedUsers));
      setMessage("User registered successfully!");
      setIsError(false);
    } else {
      // Log In validation
      const registeredUser = users.find((u) => u.email === email);

      if (!registeredUser) {
        // User not registered yet
        setMessage("No account found with this email. Please sign up first!");
        setIsError(true);
      } else if (registeredUser.password !== password) {
        // Wrong password
        setMessage("Incorrect password. Please try again.");
        setIsError(true);
      } else {
        // Success
        setMessage("Log in successful!");
        setIsError(false);
      }
    }
  };

  const toggleMode = () => {
    setIsSignUp(!isSignUp);
    setMessage("");
  };

  return (
    <div className="card">
      <h2>{isSignUp ? "Sign Up" : "Log In"}</h2>
      
      <p className="toggle-text">
        {isSignUp ? "Already a member? " : "Need an account? "}
        <span onClick={toggleMode} style={{ color: "#4a90e2", cursor: "pointer" }}>
          {isSignUp ? "Log In" : "Sign Up"}
        </span>
      </p>

      <form onSubmit={handleSubmit}>
        <div className="field">
          <label>Email</label>
          <input
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
          />
        </div>

        <div className="field">
          <label>Password</label>
          <input
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
          />
        </div>

        <button type="submit">{isSignUp ? "Sign Up" : "Log In"}</button>
      </form>

      {message && (
        <p className="message" style={{ color: isError ? "#d9534f" : "#333" }}>
          {message}
        </p>
      )}
    </div>
  );
}
